    'Create a new password with at least 8 characters. Once saved, you can sign in immediately with the updated password.':
        'कम से कम 8 अक्षरों वाला एक नया पासवर्ड बनाएं। एक बार सहेजने के बाद, आप अपडेट किए गए पासवर्ड के साथ तुरंत साइन इन कर सकते हैं।',
