    'Text Content': 'टेक्स्ट सामग्री',
    'The Discovery of India': 'भारत की खोज',
    'The `admission_inquiries` table is not available yet. Run `php artisan migrate` to create it and start seeing public website admission requests here.':
        '`प्रवेश_पूछताछ` तालिका अभी तक उपलब्ध नहीं है। इसे बनाने के लिए `पीएचपी कारीगर माइग्रेट` चलाएं और यहां सार्वजनिक वेबसाइट प्रवेश अनुरोध देखना शुरू करें।',
    'The `complaint_entries` table is not available yet. Run `php artisan migrate` to create it before using this page.':
        '`complaint_entries` तालिका अभी तक उपलब्ध नहीं है। इस पृष्ठ का उपयोग करने से पहले इसे बनाने के लिए `php artisan Migrate` चलाएँ।',
    'The `complaint_entries` table is not available yet. Run `php artisan migrate` to enable complaints.':
        '`complaint_entries` तालिका अभी तक उपलब्ध नहीं है। शिकायतें सक्षम करने के लिए `php कारीगर माइग्रेट` चलाएँ।',
    'The `front_office_admission_enquiries` table is not available yet. Run `php artisan migrate` to create it before using this page.':
        '`front_office_admission_enquiries` तालिका अभी तक उपलब्ध नहीं है। इस पृष्ठ का उपयोग करने से पहले इसे बनाने के लिए `php artisan Migrate` चलाएँ।',
    'The `phone_call_log_entries` table is not available yet. Run `php artisan migrate` to create it before using this page.':
        '`फ़ोन_कॉल_लॉग_एंट्रीज़` तालिका अभी तक उपलब्ध नहीं है। इस पृष्ठ का उपयोग करने से पहले इसे बनाने के लिए `php artisan Migrate` चलाएँ।',
    'The `postal_delivery_entries` table is not available yet. Run `php artisan migrate` to create it before using this page.':
        '`postal_delivery_entries` तालिका अभी तक उपलब्ध नहीं है। इस पृष्ठ का उपयोग करने से पहले इसे बनाने के लिए `php artisan Migrate` चलाएँ।',
    'The `postal_dispatch_entries` table is not available yet. Run `php artisan migrate` to create it before using this page.':
        '`postal_dispatch_entries` तालिका अभी तक उपलब्ध नहीं है। इस पृष्ठ का उपयोग करने से पहले इसे बनाने के लिए `php artisan Migrate` चलाएँ।',
    'The `visitor_register_entries` table is not available yet. Run `php artisan migrate` to create it before using this page.':
        '`विज़िटर_रजिस्टर_एंट्रीज़` तालिका अभी तक उपलब्ध नहीं है। इस पृष्ठ का उपयोग करने से पहले इसे बनाने के लिए `php artisan Migrate` चलाएँ।',
    'The admission form has been moved to a separate page so families can complete it without leaving the full homepage experience.':
        'प्रवेश फॉर्म को एक अलग पेज पर ले जाया गया है ताकि परिवार पूरा होमपेज अनुभव छोड़े बिना इसे पूरा कर सकें।',
    'The admission form is now available on a separate page, which makes the homepage lighter and gives families a focused application flow.':
        'प्रवेश फॉर्म अब एक अलग पृष्ठ पर उपलब्ध है, जो मुखपृष्ठ को हल्का बनाता है और परिवारों को एक केंद्रित आवेदन प्रवाह प्रदान करता है।',
    'The fee counter will remain open until 4:30 PM for the quarterly payment cycle.':
        'तिमाही भुगतान चक्र के लिए शुल्क काउंटर शाम 4:30 बजे तक खुला रहेगा।',
    'The form now lives on a dedicated admissions page for a cleaner public homepage and a more focused enquiry experience.':
        'फॉर्म अब एक स्वच्छ सार्वजनिक मुखपृष्ठ और अधिक केंद्रित पूछताछ अनुभव के लिए एक समर्पित प्रवेश पृष्ठ पर रहता है।',
    'The page keeps polling the bridge and will update automatically after the QR is scanned.':
        'पेज पुल पर मतदान करता रहता है और क्यूआर स्कैन होने के बाद अपने आप अपडेट हो जाएगा।',
    'The requested student record could not be loaded.': 'अनुरोधित छात्र रिकॉर्ड लोड नहीं किया जा सका.',
    'The status refreshes automatically every few seconds while connecting.':
        'कनेक्ट करते समय स्थिति हर कुछ सेकंड में स्वचालित रूप से ताज़ा हो जाती है।',
    'Theory + Practical': 'सिद्धांत + व्यावहारिक',
    'These images can be reused by the homepage templates.':
        'इन छवियों का मुखपृष्ठ टेम्पलेट्स द्वारा पुन: उपयोग किया जा सकता है।',
    'These rows will be skipped:': 'ये पंक्तियाँ छोड़ दी जाएंगी:',
    'These settings are stored in the database and loaded for superadmin mail usage.':
        'ये सेटिंग्स डेटाबेस में संग्रहीत की जाती हैं और सुपरएडमिन मेल उपयोग के लिए लोड की जाती हैं।',
    'These values are reused across all templates.': 'इन मानों का सभी टेम्प्लेट में पुन: उपयोग किया जाता है।',
    'This feedback campaign is closed.': 'यह फीडबैक अभियान बंद है.',
    'This message will go to all students with an available phone number.':
        'यह संदेश उपलब्ध फ़ोन नंबर वाले सभी छात्रों के पास जाएगा।',
    'This page has no content yet.': 'इस पेज पर अभी तक कोई सामग्री नहीं है.',
